package com.Marketplace_Management.Vendor.DTOs.Request;

import org.springframework.web.multipart.MultipartFile;

/**
 * The vendor profile fields shared by the create / register / update requests (their getters are
 * generated by Lombok). Each request keeps its own validation rules for them.
 */
public interface VendorProfileFields {
    String getName();
    String getDescription();
    MultipartFile getLogo();
    MultipartFile getBanner();
    String getTaxCode();
    String getEmail();
    String getAddressId();
    String getPhone();
}
